def parse_price(s: str) -> float:
    import re
    match = re.search(r'\$(\d{1,3}(?:,\d{3})*)(?:\.\d{2})?', s)
    if not match:
        return 0.0
    number_str = match.group(1).replace(',', '')
    if '.' in number_str:
        return float(number_str)
    return float(number_str) + 0.0

